// gemm, s2: two levels of Strassen on three arrays, one per leaf class (own code; generated by tasks/gemm/reference/gen_strassen.py).
//
// Three E x E arrays, one per leaf class (see the note in the generator); T = E: a weight tile is E x E. The memory holds, at scale q = log2(N / E), the 7^m weight combinations of
// m = min(q, 2) Strassen levels at 18 bits (the declared layout); a tile is one burst: E beats of low 16 bits,
// then the upper bits. Per job, in chunks of at most 16 E vectors split in 4 column parts: the chunk's
// activations are written to the on-chip buffer, one bank per activation block; then, row block by row block, for
// every product and every column block the tile is loaded into the cells' shadow registers while the previous tile
// computes, the product's activation operand (a signed sum of up to 4 blocks) streams through the array, the
// row sums are added with the product's signs into the accumulators of its result blocks, and after the row
// block's last product the result blocks are read out through the output stage into the result FIFO.
module gemm #(parameter int LGE = 2, parameter int LAT = 3) (
  input  logic                   clk, rst,
  input  logic                   job_valid,
  input  logic [3:0]             job_lgn,
  input  logic [15:0]            job_batch, job_mul,
  input  logic [5:0]             job_shift,
  input  logic [15:0]            job_zp, job_lo, job_hi,
  input  logic                   rq_ready,
  input  logic                   rd_valid,
  input  logic [16*(1<<LGE)-1:0] rd_data,
  input  logic                   x_valid,
  input  logic [16*(1<<LGE)-1:0] x_data,
  input  logic                   y_ready,
  output logic                   job_ready,
  output logic                   rq_valid,
  output logic [31:0]            rq_addr,
  output logic [23:0]            rq_len,
  output logic                   rd_ready,
  output logic                   x_ready,
  output logic                   y_valid,
  output logic [15:0]            y_vec,
  output logic [4:0]             y_row,
  output logic [16*(1<<LGE)-1:0] y_data
);
  localparam int E = 1 << LGE;
  localparam int MEMW = 16 * E;
  localparam int KW = LGE + 2;                    // a vector index inside a column part (4 E vectors)
  localparam int CBW = 5 - 2;                      // a column block inside a row part
  localparam int AW = KW + CBW;                      // an address inside a buffer bank
  localparam int LGS = (AW > 10) ? AW - 10 : 0;
  localparam int VW = LGE + 2 + 2;              // a vector index inside a chunk (16 E vectors)
  localparam int DL = E + 2;                         // from a buffer read to row 0's accumulator read
  localparam int DRAIN = 2 * E + 4;                  // from a block's last buffer read to its read-out
  localparam int CAP = 16;                           // result beats under way at most (the FIFO's size)
  localparam int LGUB = (LGE + 2 > 5) ? LGE + 2 - 5 : 0;   // log2 of a tile's beats of upper bits
  localparam int HW = (LGUB > 0) ? LGUB : 1;
  localparam int TBEATS = E + (1 << LGUB);           // beats of a tile
  localparam int ACW0 = KW + 45;               // the accumulate control of a row of array 0
  localparam int ACW1 = KW + 45;               // the accumulate control of a row of array 1
  localparam int ACW2 = KW + 20;               // the accumulate control of a row of array 2
  localparam int CW = KW + 5 + 4;               // the same, compact: valid per array, first column block, slot, vector

  // ---- the job
  logic [1:0]  mode;                                 // Strassen levels in use: min(log2(N / E), 2)
  logic [2:0]  lgh;                                  // log2 of the column blocks of a row part
  logic [CBW-1:0] hbm;                               // column blocks of a row part - 1
  logic [4:0]  nbm;                                  // N / E - 1
  logic [2-1:0] nrm;                               // row parts - 1
  logic [5-1:0] npm;                            // slots of a column block - 1
  logic [5:0] nl0, nl1, nl2;                    // products of each array (it works in the slots below that)
  logic [3*(5+1)-1:0] nl;
  logic [15:0] rem, vbase;
  logic [15:0] mul, zp, lo, hi;
  logic [5:0]  shift;
  logic [VW:0] cnt;                                  // vectors in this chunk, 1 .. 16 E
  logic [KW:0] part;                                 // vectors of a column part, ceil(cnt / 4)

  // ---- the main sequence
  typedef enum logic [2:0] {M_IDLE, M_CHUNK, M_INGEST, M_TILE, M_RUN, M_DRAIN, M_RO, M_FLUSH} mstate_t;
  mstate_t     ms;
  logic [VW:0] iv;                                   // ingest: vector of the chunk
  logic [KW-1:0] ik;                                 // ingest: vector of the column part
  logic [2-1:0] ica, ia;                           // ingest: column part, row part
  logic [4:0]  ic;                                   // ingest: beat of the vector
  logic [CBW-1:0] icb;                               // ingest: beat of the row part
  logic [CBW-1:0] rr, cc;                            // the tile: row block, column block
  logic [5-1:0] pp;                             // the product
  logic [KW:0] rv;                                   // the vector being read
  logic [15:0] dcnt;                                 // drain counter
  logic [2-1:0] ro_rho, ro_ch;                     // read-out: row part, column part
  logic [VW:0] ro_vb;                                // read-out: first vector of the column part

  // ---- registers that drive the children
  logic [2:0]      swap;
  logic            xb_rd;
  logic [AW-1:0]   xb_ra;
  logic [5-1:0] xb_pid;                         // the product whose operand is being read
  logic [E-1:0]    ld0;
  logic [(1<<HW)-1:0] ldh0;
  logic [E-1:0]    ld1;
  logic [(1<<HW)-1:0] ldh1;
  logic [E-1:0]    ld2;
  logic [(1<<HW)-1:0] ldh2;
  logic [MEMW-1:0] wbeat;
  logic [(DL-1)*CW-1:0] actl;                        // the accumulate control on its way to row 0, compact
  logic [ACW0-1:0] acw0, acw_n0;                  // decoded, at row 0 of array 0
  logic [ACW1-1:0] acw1, acw_n1;                  // decoded, at row 0 of array 1
  logic [ACW2-1:0] acw2, acw_n2;                  // decoded, at row 0 of array 2
  logic            r_rd;
  logic [4-1:0] r_g;
  logic [2-1:0] r_sub;
  logic [KW-1:0]   r_v;
  logic [20:0]     r_tag;                            // the position (vector, row block) of the beat being read out
  logic [2:0]      r_use, r_use1, r_use2;            // the arrays that hold a part of the beat read out
  logic [8-1:0] t_valid;                          // read-out pipeline: valid, and the beat's position
  logic [8*21-1:0] t_tag;
  logic [4:0]      occ;                              // result beats issued and not yet transferred

  // ---- the weight loader
  typedef enum logic [1:0] {L_IDLE, L_REQ, L_RX} lstate_t;
  lstate_t     ls;
  logic [12:0] tiles;                                // tiles of this chunk not yet requested
  logic [5-1:0] lp;
  logic [CBW-1:0] lr, lc;
  logic [LGE:0] li;
  logic [1:0]  ll;                                   // the array being loaded
  logic        lmore;                                // another array's tile follows in this slot
  logic        sh_full;
  logic [15:0] wave;                                 // cycles until the last swap has passed every cell

  logic [MEMW*(16<<LGS)-1:0] xq;
  logic [5-1:0] xqpid;
  logic [LGS:0]    xqsb;
  logic [E-1:0]    sk_swap0;
  logic [18*E-1:0] sk_x0;
  logic [48*E-1:0] ad0;
  logic [E-1:0]    sk_swap1;
  logic [18*E-1:0] sk_x1;
  logic [48*E-1:0] ad1;
  logic [E-1:0]    sk_swap2;
  logic [18*E-1:0] sk_x2;
  logic [48*E-1:0] ad2;
  logic [MEMW-1:0] ya;
  logic            f_valid;
  logic [MEMW+20:0] f_dout;

  gemm_xbuf #(.LGE(LGE)) xbuf (
    .clk(clk), .we_v(x_valid), .we_r(x_ready), .wblk({ia, ica}), .waddr({ik, icb}), .wdata(x_data),
    .rd(xb_rd), .rmode(mode), .rpid(xb_pid), .raddr(xb_ra),
    .q(xq), .qpid(xqpid), .qsb(xqsb));
  gemm_skew_a #(.LGE(LGE)) skew0 (
    .clk(clk), .swap(swap[0]), .q(xq), .mode(mode), .qpid(xqpid), .qsb(xqsb),
    .swap_o(sk_swap0), .x_o(sk_x0));
  gemm_array_a #(.LGE(LGE)) array0 (
    .clk(clk), .ld(ld0), .ld_hi(ldh0), .w_d(wbeat), .swap(sk_swap0), .x(sk_x0), .acw(acw0),
    .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v), .d(ad0));
  gemm_skew_b #(.LGE(LGE)) skew1 (
    .clk(clk), .swap(swap[1]), .q(xq), .mode(mode), .qpid(xqpid), .qsb(xqsb),
    .swap_o(sk_swap1), .x_o(sk_x1));
  gemm_array_b #(.LGE(LGE)) array1 (
    .clk(clk), .ld(ld1), .ld_hi(ldh1), .w_d(wbeat), .swap(sk_swap1), .x(sk_x1), .acw(acw1),
    .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v), .d(ad1));
  gemm_skew_c #(.LGE(LGE)) skew2 (
    .clk(clk), .swap(swap[2]), .q(xq), .mode(mode), .qpid(xqpid), .qsb(xqsb),
    .swap_o(sk_swap2), .x_o(sk_x2));
  gemm_array_c #(.LGE(LGE)) array2 (
    .clk(clk), .ld(ld2), .ld_hi(ldh2), .w_d(wbeat), .swap(sk_swap2), .x(sk_x2), .acw(acw2),
    .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v), .d(ad2));
  gemm_outs #(.LGE(LGE)) outs (
    .clk(clk), .d0(ad0), .d1(ad1), .d2(ad2), .use_d(r_use2), .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi),
    .y(ya));
  gemm_fifo #(.W(MEMW + 21), .LGD(4)) fifo (
    .clk(clk), .rst(rst), .push(t_valid[8-1]), .din({t_tag[(8-1)*21 +: 21], ya}), .pop_ready(y_ready),
    .valid(f_valid), .dout(f_dout));
  assign y_valid = f_valid;
  assign y_data  = f_dout[MEMW-1:0];
  assign y_row   = f_dout[MEMW +: 5];
  assign y_vec   = f_dout[MEMW+5 +: 16];

  // ---- the product tables (constants of the algorithm): by {mode, product}; the operands' table is in the
  // buffer and in the skew, which get the product's number
  logic [45-1:0] ptt0;                          // the targets of array 0: per group {slot, first, negate, enable}
  logic [45-1:0] ptt1;                          // the targets of array 1: per group {slot, first, negate, enable}
  logic [20-1:0] ptt2;                          // the targets of array 2: per group {slot, first, negate, enable}
  logic [17:0] psg;                                  // the loader's slot: per array its weight segment
  logic [5:0]  pseg;
  logic [2:0]  ytu;                                  // read-out: the arrays that hold a part of the block
  logic [4+2-1:0] ygs;                         // read-out: the block's {group, slot}
  logic [5-1:0] a_pid;
  assign a_pid = actl[(DL-1)*CW-5 -: 5];
  always_comb begin
    case ({mode, a_pid})
      7'd0: ptt0 = 45'h500000;
      7'd1: ptt0 = 45'ha000000;
      7'd2: ptt0 = 45'h2800000000;
      7'd3: ptt0 = 45'h50000000000;
      7'd32: ptt0 = 45'h528000;
      7'd33: ptt0 = 45'h1a018000;
      7'd34: ptt0 = 45'ha008000;
      7'd35: ptt0 = 45'h12100000;
      7'd36: ptt0 = 45'h2300000;
      7'd37: ptt0 = 45'h8000;
      7'd38: ptt0 = 45'h100000;
      7'd39: ptt0 = 45'h2940000000;
      7'd40: ptt0 = 45'hd00c0000000;
      7'd41: ptt0 = 45'h50040000000;
      7'd42: ptt0 = 45'h90800000000;
      7'd43: ptt0 = 45'h11800000000;
      7'd44: ptt0 = 45'h40000000;
      7'd45: ptt0 = 45'h800000000;
      7'd64: ptt0 = 45'h1a03b407;
      7'd65: ptt0 = 45'ha7014e0;
      7'd66: ptt0 = 45'h6b40000063;
      7'd67: ptt0 = 45'h1d02c0002c01;
      7'd68: ptt0 = 45'h150240000c03;
      7'd69: ptt0 = 45'h194800002c60;
      7'd70: ptt0 = 45'h115800000c20;
      7'd71: ptt0 = 45'h240000003;
      7'd72: ptt0 = 45'h4800000060;
      7'd73: ptt0 = 45'hd01c0002403;
      7'd74: ptt0 = 45'h53800000460;
      7'd75: ptt0 = 45'h1902d2018000;
      7'd76: ptt0 = 45'h115802300000;
      7'd77: ptt0 = 45'h840318000;
      7'd78: ptt0 = 45'h900d6008000;
      7'd79: ptt0 = 45'h10046018000;
      7'd80: ptt0 = 45'h90816300000;
      7'd81: ptt0 = 45'h11806100000;
      7'd82: ptt0 = 45'h40018000;
      7'd83: ptt0 = 45'h800300000;
      7'd84: ptt0 = 45'h2403;
      7'd85: ptt0 = 45'h460;
      7'd86: ptt0 = 45'h12018000;
      7'd87: ptt0 = 45'h2300000;
      default: ptt0 = '0;
    endcase
  end
  always_comb begin
    case ({mode, a_pid})
      7'd64: ptt1 = 45'ha029405;
      7'd65: ptt1 = 45'h1a5034a0;
      7'd66: ptt1 = 45'h2940000021;
      7'd67: ptt1 = 45'h50040000401;
      7'd68: ptt1 = 45'hd0800002420;
      7'd69: ptt1 = 45'h40000001;
      7'd70: ptt1 = 45'h800000020;
      7'd71: ptt1 = 45'h6b40108000;
      7'd72: ptt1 = 45'h150242008000;
      7'd73: ptt1 = 45'h1d4812100000;
      7'd74: ptt1 = 45'h240008000;
      7'd75: ptt1 = 45'h4800100000;
      7'd76: ptt1 = 45'h401;
      7'd77: ptt1 = 45'h2420;
      7'd78: ptt1 = 45'h2008000;
      7'd79: ptt1 = 45'h12100000;
      default: ptt1 = '0;
    endcase
  end
  always_comb begin
    case ({mode, a_pid})
      7'd64: ptt2 = 20'h294a5;
      7'd65: ptt2 = 20'h401;
      7'd66: ptt2 = 20'h8020;
      7'd67: ptt2 = 20'h21;
      7'd68: ptt2 = 20'h1;
      7'd69: ptt2 = 20'h20;
      7'd70: ptt2 = 20'h8400;
      7'd71: ptt2 = 20'h400;
      7'd72: ptt2 = 20'h8000;
      default: ptt2 = '0;
    endcase
  end
  always_comb begin
    case ({mode, lp})
      7'd0: psg = 18'h0;
      7'd1: psg = 18'h0;
      7'd2: psg = 18'h0;
      7'd3: psg = 18'h0;
      7'd32: psg = 18'h0;
      7'd33: psg = 18'h1;
      7'd34: psg = 18'h2;
      7'd35: psg = 18'h3;
      7'd36: psg = 18'h4;
      7'd37: psg = 18'h5;
      7'd38: psg = 18'h6;
      7'd39: psg = 18'h0;
      7'd40: psg = 18'h1;
      7'd41: psg = 18'h2;
      7'd42: psg = 18'h3;
      7'd43: psg = 18'h4;
      7'd44: psg = 18'h5;
      7'd45: psg = 18'h6;
      7'd64: psg = 18'h81;
      7'd65: psg = 18'h50c4;
      7'd66: psg = 18'h6387;
      7'd67: psg = 18'h23408;
      7'd68: psg = 18'h28449;
      7'd69: psg = 18'h294ca;
      7'd70: psg = 18'h2a50b;
      7'd71: psg = 18'h2f54c;
      7'd72: psg = 18'h305cd;
      7'd73: psg = 18'h60f;
      7'd74: psg = 18'h692;
      7'd75: psg = 18'h6d6;
      7'd76: psg = 18'h959;
      7'd77: psg = 18'h99c;
      7'd78: psg = 18'hb1d;
      7'd79: psg = 18'hb5e;
      7'd80: psg = 18'h1f;
      7'd81: psg = 18'h20;
      7'd82: psg = 18'h21;
      7'd83: psg = 18'h22;
      7'd84: psg = 18'h24;
      7'd85: psg = 18'h27;
      7'd86: psg = 18'h2b;
      7'd87: psg = 18'h2e;
      default: psg = '0;
    endcase
  end
  assign pseg = (ll == 2'd0) ? psg[5:0] : (ll == 2'd1) ? psg[11:6] : psg[17:12];
  always_comb begin
    case ({mode, ro_rho, ro_ch})
      6'd0: ytu = 3'd1;
      6'd1: ytu = 3'd1;
      6'd2: ytu = 3'd1;
      6'd3: ytu = 3'd1;
      6'd4: ytu = 3'd0;
      6'd5: ytu = 3'd0;
      6'd6: ytu = 3'd0;
      6'd7: ytu = 3'd0;
      6'd8: ytu = 3'd0;
      6'd9: ytu = 3'd0;
      6'd10: ytu = 3'd0;
      6'd11: ytu = 3'd0;
      6'd12: ytu = 3'd0;
      6'd13: ytu = 3'd0;
      6'd14: ytu = 3'd0;
      6'd15: ytu = 3'd0;
      6'd16: ytu = 3'd1;
      6'd17: ytu = 3'd1;
      6'd18: ytu = 3'd1;
      6'd19: ytu = 3'd1;
      6'd20: ytu = 3'd1;
      6'd21: ytu = 3'd1;
      6'd22: ytu = 3'd1;
      6'd23: ytu = 3'd1;
      6'd24: ytu = 3'd0;
      6'd25: ytu = 3'd0;
      6'd26: ytu = 3'd0;
      6'd27: ytu = 3'd0;
      6'd28: ytu = 3'd0;
      6'd29: ytu = 3'd0;
      6'd30: ytu = 3'd0;
      6'd31: ytu = 3'd0;
      6'd32: ytu = 3'd7;
      6'd33: ytu = 3'd3;
      6'd34: ytu = 3'd3;
      6'd35: ytu = 3'd3;
      6'd36: ytu = 3'd3;
      6'd37: ytu = 3'd7;
      6'd38: ytu = 3'd3;
      6'd39: ytu = 3'd3;
      6'd40: ytu = 3'd3;
      6'd41: ytu = 3'd3;
      6'd42: ytu = 3'd7;
      6'd43: ytu = 3'd3;
      6'd44: ytu = 3'd3;
      6'd45: ytu = 3'd3;
      6'd46: ytu = 3'd3;
      6'd47: ytu = 3'd7;
      default: ytu = '0;
    endcase
  end
  always_comb begin
    case ({ro_rho, ro_ch})
      4'd0: ygs = 6'd16;
      4'd1: ygs = 6'd20;
      4'd2: ygs = 6'd28;
      4'd3: ygs = 6'd32;
      4'd4: ygs = 6'd21;
      4'd5: ygs = 6'd12;
      4'd6: ygs = 6'd33;
      4'd7: ygs = 6'd24;
      4'd8: ygs = 6'd29;
      4'd9: ygs = 6'd34;
      4'd10: ygs = 6'd4;
      4'd11: ygs = 6'd8;
      4'd12: ygs = 6'd35;
      4'd13: ygs = 6'd25;
      4'd14: ygs = 6'd9;
      4'd15: ygs = 6'd0;
      default: ygs = '0;
    endcase
  end
  logic [2:0]  jq;
  logic [1:0]  jmode;
  assign jq    = 3'(job_lgn - 4'(LGE));
  assign jmode = (jq > 3'd2) ? 2'd2 : jq[1:0];
  always_comb begin
    case (mode)
      2'd0: nl = 18'd4;
      2'd1: nl = 18'd14;
      2'd2: nl = 18'd37912;
      default: nl = '0;
    endcase
  end
  assign nl0 = nl[5:0];
  assign nl1 = nl[2*5+1:5+1];
  assign nl2 = nl[3*5+2:2*5+2];
  assign npm = 5'(nl0 - 1'b1);

  logic        x_take, y_take, start_pass, ro_go, rd_take, a_cb0, ro_pad, lnext;
  logic [2:0]  a_val, act;
  logic [VW:0] cnt_n, ro_v;
  logic [31:0] tix;
  logic [HW-1:0] hix;
  assign x_take     = x_valid & x_ready;
  assign y_take     = y_valid & y_ready;
  assign rd_take    = rd_valid & rd_ready;
  assign start_pass = (ms == M_TILE) & sh_full & ~xb_rd;   // one idle cycle between passes (the row memories)
  assign ro_go      = (ms == M_RO) & (occ < CAP[4:0]);
  assign cnt_n      = (rem > 16'(1 << VW)) ? (VW+1)'(1 << VW) : rem[VW:0];
  assign ro_v       = ro_vb + (VW+1)'(rv);
  assign ro_pad     = (ro_v >= cnt);                       // a padding vector: nothing to read out
  assign a_val      = actl[(DL-1)*CW-1 -: 3];
  assign a_cb0      = actl[(DL-1)*CW-4];
  assign act        = {((5+1)'(pp) < nl2), ((5+1)'(pp) < nl1), ((5+1)'(pp) < nl0)};
  assign lnext      = (ll == 2'd0) ? ((5+1)'(lp) < nl1) : (ll == 2'd1) ? ((5+1)'(lp) < nl2) : 1'b0;
  assign acw_n0[KW-1:0] = actl[(DL-2)*CW +: KW];
  for (genvar g = 0; g < 9; g++) begin : g_dec0
    assign acw_n0[KW + 5*g]            = a_val[0] & ptt0[5*g];
    assign acw_n0[KW + 5*g + 1]        = ptt0[5*g + 1];
    assign acw_n0[KW + 5*g + 2]        = a_cb0 & ptt0[5*g + 2];
    assign acw_n0[KW + 5*g + 3 +: 2] = ptt0[5*g + 3 +: 2];
  end
  assign acw_n1[KW-1:0] = actl[(DL-2)*CW +: KW];
  for (genvar g = 0; g < 9; g++) begin : g_dec1
    assign acw_n1[KW + 5*g]            = a_val[1] & ptt1[5*g];
    assign acw_n1[KW + 5*g + 1]        = ptt1[5*g + 1];
    assign acw_n1[KW + 5*g + 2]        = a_cb0 & ptt1[5*g + 2];
    assign acw_n1[KW + 5*g + 3 +: 2] = ptt1[5*g + 3 +: 2];
  end
  assign acw_n2[KW-1:0] = actl[(DL-2)*CW +: KW];
  for (genvar g = 0; g < 4; g++) begin : g_dec2
    assign acw_n2[KW + 5*g]            = a_val[2] & ptt2[5*g];
    assign acw_n2[KW + 5*g + 1]        = ptt2[5*g + 1];
    assign acw_n2[KW + 5*g + 2]        = a_cb0 & ptt2[5*g + 2];
    assign acw_n2[KW + 5*g + 3 +: 2] = ptt2[5*g + 3 +: 2];
  end
  assign tix = (((32'(pseg) << lgh) + 32'(lr)) << lgh) + 32'(lc);
  if (LGUB == 0) begin : g_h1
    assign hix = '0;
  end else begin : g_hn
    assign hix = li[LGUB-1:0];
  end

  always_ff @(posedge clk) begin
    // the accumulate control's delay line and the read-out pipeline
    actl    <= {actl[(DL-2)*CW-1:0], (act & {3{(ms == M_RUN) | start_pass}}), (cc == '0), pp, (start_pass ? KW'(0) : rv[KW-1:0])};
    acw0    <= acw_n0;
    acw1    <= acw_n1;
    acw2    <= acw_n2;
    r_use1  <= r_use;
    r_use2  <= r_use1;
    t_valid <= {t_valid[8-2:0], r_rd};
    t_tag   <= {t_tag[(8-1)*21-1:0], r_tag};
    if (rd_take) wbeat <= rd_data;

    if (rst) begin
      ms        <= M_IDLE;
      job_ready <= 1'b0;
      x_ready   <= 1'b0;
      swap      <= 3'd0;
      xb_rd     <= 1'b0;
      r_rd      <= 1'b0;
      t_valid   <= '0;
      ll        <= 2'd0;
      occ       <= 5'd0;
      ls        <= L_IDLE;
      rq_valid  <= 1'b0;
      rd_ready  <= 1'b0;
      ld0       <= '0;
      ldh0      <= '0;
      ld1       <= '0;
      ldh1      <= '0;
      ld2       <= '0;
      ldh2      <= '0;
      tiles     <= 13'd0;
      sh_full   <= 1'b0;
      wave      <= 16'd0;
      rq_addr   <= 32'd0;
      rq_len    <= 24'd0;
    end else begin
      swap  <= 3'd0;
      xb_rd <= 1'b0;
      r_rd  <= 1'b0;
      occ   <= occ + {4'd0, (ro_go & ~ro_pad)} - {4'd0, y_take};
      if (wave != 16'd0) wave <= wave - 16'd1;

      case (ms)
        M_IDLE: begin
          if (job_valid & job_ready) begin
            job_ready <= 1'b0;
            mode  <= jmode;
            lgh   <= jq - 3'(jmode);
            hbm   <= CBW'((6'd1 << (jq - 3'(jmode))) - 6'd1);
            nbm   <= 5'((6'd1 << jq) - 6'd1);
            nrm   <= 2'((3'd1 << jmode) - 3'd1);
            rem   <= job_batch;
            vbase <= 16'd0;
            mul   <= job_mul;
            shift <= job_shift;
            zp    <= job_zp;
            lo    <= job_lo;
            hi    <= job_hi;
            ms    <= M_CHUNK;
          end else
            job_ready <= 1'b1;
        end
        M_CHUNK: begin                               // the next chunk of the job: at most 16 E vectors
          cnt   <= cnt_n;
          part  <= (KW+1)'((cnt_n + (VW+1)'(4 - 1)) >> 2);
          tiles <= 13'(((13'(npm) + 13'd1) << lgh) << lgh);
          lp    <= '0;
          lr    <= '0;
          lc    <= '0;
          iv    <= '0;
          ik    <= '0;
          ica   <= '0;
          ia    <= '0;
          ic    <= 5'd0;
          icb   <= '0;
          x_ready <= 1'b1;
          ms    <= M_INGEST;
        end
        M_INGEST: begin
          if (x_take) begin
            if (ic == nbm) begin
              ic  <= 5'd0;
              icb <= '0;
              ia  <= '0;
              iv  <= iv + 1'b1;
              if ((KW+1)'(ik) + 1'b1 == part) begin
                ik  <= '0;
                ica <= ica + 1'b1;
              end else
                ik <= ik + 1'b1;
              if (iv + 1'b1 == cnt) begin
                x_ready <= 1'b0;
                ms <= M_TILE;
                rr <= '0;
                cc <= '0;
                pp <= '0;
              end
            end else begin
              ic <= ic + 5'd1;
              if (icb == hbm) begin
                icb <= '0;
                ia  <= ia + 1'b1;
              end else
                icb <= icb + 1'b1;
            end
          end
        end
        M_TILE: begin
          if (start_pass) begin                      // the tile is in the shadow registers: start its pass
            swap    <= act;
            sh_full <= 1'b0;
            wave    <= 16'(E - 1);
            xb_rd   <= 1'b1;
            xb_ra   <= {KW'(0), cc};
            xb_pid  <= pp;
            rv      <= (KW+1)'(1);
            dcnt    <= 16'(DRAIN);
            if (part == (KW+1)'(1)) begin
if (cc == hbm) begin
  cc <= '0;
  if (pp == npm) begin
    pp <= '0;
    ms <= M_DRAIN;
  end else begin
    pp <= pp + 1'b1;
    ms <= M_TILE;
  end
end else begin
  cc <= cc + 1'b1;
  ms <= M_TILE;
end
            end else
              ms <= M_RUN;
          end
        end
        M_RUN: begin
          xb_rd <= 1'b1;
          xb_ra <= {rv[KW-1:0], cc};
          rv    <= rv + 1'b1;
          dcnt  <= 16'(DRAIN);
          if (rv + 1'b1 == part) begin
if (cc == hbm) begin
  cc <= '0;
  if (pp == npm) begin
    pp <= '0;
    ms <= M_DRAIN;
  end else begin
    pp <= pp + 1'b1;
    ms <= M_TILE;
  end
end else begin
  cc <= cc + 1'b1;
  ms <= M_TILE;
end
          end
        end
        M_DRAIN: begin                               // the block's last sums are on their way to the row memories
          dcnt   <= dcnt - 16'd1;
          rv     <= '0;
          ro_rho <= '0;
          ro_ch  <= '0;
          ro_vb  <= '0;
          if (dcnt == 16'd0) ms <= M_RO;
        end
        M_RO: begin
          if (ro_go) begin
            r_rd  <= ~ro_pad;
            r_use <= ytu;
            r_g   <= ygs[2 +: 4];
            r_sub <= ygs[2-1:0];
            r_v   <= rv[KW-1:0];
            r_tag <= {vbase + 16'(ro_v), (5'(ro_rho) << lgh) | 5'(rr)};
            if (rv + 1'b1 == part) begin
              rv <= '0;
              if (ro_ch == 2'd3) begin
                ro_ch <= '0;
                ro_vb <= '0;
                if (ro_rho == nrm) begin
                  if (rr == hbm) ms <= M_FLUSH;
                  else begin
                    rr <= rr + 1'b1;
                    ms <= M_TILE;
                  end
                end else
                  ro_rho <= ro_rho + 1'b1;
              end else begin
                ro_ch <= ro_ch + 1'b1;
                ro_vb <= ro_vb + (VW+1)'(part);
              end
            end else
              rv <= rv + 1'b1;
          end
        end
        M_FLUSH: begin                               // the chunk's last results leave the output stage
          if (~r_rd & (t_valid == '0)) begin
            vbase <= vbase + 16'(cnt);
            rem   <= rem - 16'(cnt);
            if (rem == 16'(cnt)) begin
              ms <= M_IDLE;
              job_ready <= 1'b1;
            end else
              ms <= M_CHUNK;
          end
        end
        default: ms <= M_IDLE;
      endcase

      // the weight loader: one burst per tile; the tiles of the next slot (one per array that works in it) are
      // loaded one after the other into the arrays' shadow registers, one slot ahead of the arrays
      ld0  <= '0;
      ldh0 <= '0;
      ld1  <= '0;
      ldh1 <= '0;
      ld2  <= '0;
      ldh2 <= '0;
      case (ls)
        L_IDLE: begin
          if ((tiles != 13'd0) & ~sh_full & ~start_pass & (ms != M_IDLE) & (ms != M_CHUNK)) begin
            rq_valid <= 1'b1;
            rq_addr  <= (tix << LGE) + (tix << LGUB);
            rq_len   <= 24'(TBEATS);
            ls       <= L_REQ;
          end
        end
        L_REQ: begin
          if (rq_valid & rq_ready) begin
            rq_valid <= 1'b0;
            ls       <= L_RX;
            li       <= '0;
            lmore    <= lnext;
            if (~lnext) begin                        // the slot's last tile: the loader's next slot
              tiles <= tiles - 13'd1;
              if (lc == hbm) begin
                lc <= '0;
                if (lp == npm) begin
                  lp <= '0;
                  lr <= lr + 1'b1;
                end else
                  lp <= lp + 1'b1;
              end else
                lc <= lc + 1'b1;
            end
          end
        end
        L_RX: begin
          // a beat may land in the shadow registers only when the last swap has passed (wave = 0)
          rd_ready <= (wave <= 16'd1) & ~(rd_take & (li == (LGE+1)'(TBEATS - 1)));
          if (rd_take) begin
            if (ll == 2'd0) begin
              if (~li[LGE]) ld0[li[LGE-1:0]] <= 1'b1;
              else          ldh0[hix] <= 1'b1;
            end
            if (ll == 2'd1) begin
              if (~li[LGE]) ld1[li[LGE-1:0]] <= 1'b1;
              else          ldh1[hix] <= 1'b1;
            end
            if (ll == 2'd2) begin
              if (~li[LGE]) ld2[li[LGE-1:0]] <= 1'b1;
              else          ldh2[hix] <= 1'b1;
            end
            li <= li + 1'b1;
            if (li == (LGE+1)'(TBEATS - 1)) begin
              ls <= L_IDLE;
              if (lmore) ll <= ll + 2'd1;
              else begin
                ll      <= 2'd0;
                sh_full <= 1'b1;
              end
            end
          end
        end
        default: ls <= L_IDLE;
      endcase
    end
  end
endmodule

// The activation buffer: one bank per activation block (row part, column part), so that the up to 10 blocks of
// an operand are read in one cycle. A bank holds 4 E vectors of up to 32 / 4 beats, in 64-bit blocks.
// `q` is every bank's output; `qpid` (the product) and `qsb` (the sub-bank) say which words were read.
module gemm_xbuf #(parameter int LGE = 2) (
  input  logic                   clk,
  input  logic                   we_v, we_r,
  input  logic [4-1:0]        wblk,
  input  logic [LGE+5-1:0]   waddr,
  input  logic [16*(1<<LGE)-1:0] wdata,
  input  logic                   rd,
  input  logic [1:0]             rmode,
  input  logic [5-1:0]      rpid,
  input  logic [LGE+5-1:0]   raddr,
  output logic [(16<<LGE)*(16<<((LGE+5>10)?LGE+5-10:0))-1:0] q,
  output logic [5-1:0]      qpid,
  output logic [((LGE+5>10)?LGE+5-10:0):0] qsb
);
  localparam int MEMW = 16 << LGE;
  localparam int AW = LGE + 5;
  localparam int LGS = (AW > 10) ? AW - 10 : 0;       // log2 of the 1024-word sub-banks of a bank
  logic            we;
  logic [LGS:0]    wsb, rsb;
  logic [60-1:0] ptx;                             // the operand of product rpid: per term {use, negate, block}
  assign we = we_v & we_r;
  always_comb begin
    case ({rmode, rpid})
      7'd0: ptx = 60'h20;
      7'd1: ptx = 60'h21;
      7'd2: ptx = 60'h22;
      7'd3: ptx = 60'h23;
      7'd32: ptx = 60'h960;
      7'd33: ptx = 60'h20;
      7'd34: ptx = 60'hd61;
      7'd35: ptx = 60'hc24;
      7'd36: ptx = 60'h25;
      7'd37: ptx = 60'h860;
      7'd38: ptx = 60'h964;
      7'd39: ptx = 60'h9e2;
      7'd40: ptx = 60'h22;
      7'd41: ptx = 60'hde3;
      7'd42: ptx = 60'hca6;
      7'd43: ptx = 60'h27;
      7'd44: ptx = 60'h8e2;
      7'd45: ptx = 60'h9e6;
      7'd64: ptx = 60'hbea960febd61aa0;
      7'd65: ptx = 60'haea860eaec24be5;
      7'd66: ptx = 60'hbee964ffa9e2960;
      7'd67: ptx = 60'h9e2960bfbde3020;
      7'd68: ptx = 60'h8e2860abeca6d61;
      7'd69: ptx = 60'h9e6964efa8e2c24;
      7'd70: ptx = 60'hbeab68ffe9e6025;
      7'd71: ptx = 60'haeaa68d70b68860;
      7'd72: ptx = 60'hbeeb6c971f69964;
      7'd73: ptx = 60'h834e2cea2;
      7'd74: ptx = 60'hc70a68fe7;
      7'd75: ptx = 60'hd74b6cc28;
      7'd76: ptx = 60'hde3d61d6d;
      7'd77: ptx = 60'hca6c24bea;
      7'd78: ptx = 60'hfebf6902a;
      7'd79: ptx = 60'heaee2cfeb;
      7'd80: ptx = 60'heae;
      7'd81: ptx = 60'h2f;
      7'd82: ptx = 60'haea;
      7'd83: ptx = 60'hbee;
      7'd84: ptx = 60'h8a0;
      7'd85: ptx = 60'h9e5;
      7'd86: ptx = 60'haa8;
      7'd87: ptx = 60'hbed;
      default: ptx = '0;
    endcase
  end
  if (LGS == 0) begin : g_one
    assign wsb = '0;
    assign rsb = '0;
  end else begin : g_many
    assign wsb = {1'b0, waddr[AW-1:10]};
    assign rsb = {1'b0, raddr[AW-1:10]};
  end
  for (genvar b = 0; b < 16; b++) begin : g_bank
    logic hit;
    assign hit = (ptx[5] & (ptx[0 +: 4] == b)) | (ptx[11] & (ptx[6 +: 4] == b)) | (ptx[17] & (ptx[12 +: 4] == b)) | (ptx[23] & (ptx[18 +: 4] == b)) | (ptx[29] & (ptx[24 +: 4] == b)) | (ptx[35] & (ptx[30 +: 4] == b)) | (ptx[41] & (ptx[36 +: 4] == b)) | (ptx[47] & (ptx[42 +: 4] == b)) | (ptx[53] & (ptx[48 +: 4] == b)) | (ptx[59] & (ptx[54 +: 4] == b));
    for (genvar sb = 0; sb < (1 << LGS); sb++) begin : g_sub
      logic bw, br;
      assign bw = we & (wblk == b) & (wsb == sb);
      assign br = rd & hit & (rsb == sb) & ~bw;
      for (genvar k = 0; k < MEMW / 64; k++) begin : g_blk
        if (AW <= 8) begin : g_256
          srambank_64x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? 8'(waddr) : 8'(raddr)), .wd(wdata[64*k +: 64]),
                                    .banksel(bw | br), .read(br), .write(bw),
                                    .dataout(q[MEMW*((b << LGS) + sb) + 64*k +: 64]));
        end else if (AW == 9) begin : g_512
          srambank_128x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? 9'(waddr) : 9'(raddr)), .wd(wdata[64*k +: 64]),
                                     .banksel(bw | br), .read(br), .write(bw),
                                     .dataout(q[MEMW*((b << LGS) + sb) + 64*k +: 64]));
        end else begin : g_1024
          srambank_256x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? 10'(waddr) : 10'(raddr)), .wd(wdata[64*k +: 64]),
                                     .banksel(bw | br), .read(br), .write(bw),
                                     .dataout(q[MEMW*((b << LGS) + sb) + 64*k +: 64]));
        end
      end
    end
  end
  always_ff @(posedge clk)
    if (rd) begin
      qpid <= rpid;
      qsb  <= rsb;
    end
endmodule

// The operand and the input skew: the up to 2 blocks read from the buffer are added with their signs, entry by
// entry (a signed 18-bit operand), and column j of the result (and the swap tag) is delayed j + 1 cycles, so
// that every cell of a row sees its activation one cycle after its left neighbour's sum.
module gemm_skew_a #(parameter int LGE = 2) (
  input  logic                   clk,
  input  logic                   swap,
  input  logic [(16<<LGE)*(16<<((LGE+5>10)?LGE+5-10:0))-1:0] q,
  input  logic [1:0]             mode,
  input  logic [5-1:0]      qpid,
  input  logic [((LGE+5>10)?LGE+5-10:0):0] qsb,
  output logic [(1<<LGE)-1:0]    swap_o,
  output logic [18*(1<<LGE)-1:0] x_o
);
  localparam int E = 1 << LGE;
  localparam int MEMW = 16 * E;
  localparam int AW = LGE + 5;
  localparam int LGS = (AW > 10) ? AW - 10 : 0;
  logic [2*(2+4)-1:0] ptx;                    // the operand of product qpid: per term {use, negate, block}
  logic [2*4-1:0] qblk;
  logic [2-1:0] quse, qneg;
  always_comb begin
    case ({mode, qpid})
      7'd0: ptx = 12'h20;
      7'd1: ptx = 12'h21;
      7'd2: ptx = 12'h22;
      7'd3: ptx = 12'h23;
      7'd32: ptx = 12'h960;
      7'd33: ptx = 12'h20;
      7'd34: ptx = 12'hd61;
      7'd35: ptx = 12'hc24;
      7'd36: ptx = 12'h25;
      7'd37: ptx = 12'h860;
      7'd38: ptx = 12'h964;
      7'd39: ptx = 12'h9e2;
      7'd40: ptx = 12'h22;
      7'd41: ptx = 12'hde3;
      7'd42: ptx = 12'hca6;
      7'd43: ptx = 12'h27;
      7'd44: ptx = 12'h8e2;
      7'd45: ptx = 12'h9e6;
      7'd64: ptx = 12'haa0;
      7'd65: ptx = 12'hbe5;
      7'd66: ptx = 12'h960;
      7'd67: ptx = 12'h20;
      7'd68: ptx = 12'hd61;
      7'd69: ptx = 12'hc24;
      7'd70: ptx = 12'h25;
      7'd71: ptx = 12'h860;
      7'd72: ptx = 12'h964;
      7'd73: ptx = 12'hea2;
      7'd74: ptx = 12'hfe7;
      7'd75: ptx = 12'hc28;
      7'd76: ptx = 12'hd6d;
      7'd77: ptx = 12'hbea;
      7'd78: ptx = 12'h2a;
      7'd79: ptx = 12'hfeb;
      7'd80: ptx = 12'heae;
      7'd81: ptx = 12'h2f;
      7'd82: ptx = 12'haea;
      7'd83: ptx = 12'hbee;
      7'd84: ptx = 12'h8a0;
      7'd85: ptx = 12'h9e5;
      7'd86: ptx = 12'haa8;
      7'd87: ptx = 12'hbed;
      default: ptx = '0;
    endcase
  end
  for (genvar t = 0; t < 2; t++) begin : g_op
    assign qblk[4*t +: 4] = ptx[(2+4)*t +: 4];
    assign qneg[t] = ptx[(2+4)*t + 4];
    assign quse[t] = ptx[(2+4)*t + 4 + 1];
  end
  logic [MEMW*16-1:0] w;                          // per bank: the word of the sub-bank that was read
  for (genvar b = 0; b < 16; b++) begin : g_b
    if (LGS == 0) begin : g_1
      assign w[MEMW*b +: MEMW] = q[MEMW*b +: MEMW];
    end else if (LGS == 1) begin : g_2
      assign w[MEMW*b +: MEMW] = qsb[0] ? q[MEMW*(2*b+1) +: MEMW] : q[MEMW*(2*b) +: MEMW];
    end else begin : g_4                             // LGE <= 7: at most four sub-banks
      assign w[MEMW*b +: MEMW] = qsb[1] ? (qsb[0] ? q[MEMW*(4*b+3) +: MEMW] : q[MEMW*(4*b+2) +: MEMW])
                                        : (qsb[0] ? q[MEMW*(4*b+1) +: MEMW] : q[MEMW*(4*b) +: MEMW]);
    end
  end
  logic [MEMW*2-1:0] xt;                         // per term: the selected bank's beat, an OR over the banks
  for (genvar t = 0; t < 2; t++) begin : g_term
    assign xt[MEMW*t +: MEMW] = ((qblk[4*t +: 4] == 4'd0) ? w[MEMW*0 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd1) ? w[MEMW*1 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd2) ? w[MEMW*2 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd3) ? w[MEMW*3 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd4) ? w[MEMW*4 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd5) ? w[MEMW*5 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd6) ? w[MEMW*6 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd7) ? w[MEMW*7 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd8) ? w[MEMW*8 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd9) ? w[MEMW*9 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd10) ? w[MEMW*10 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd11) ? w[MEMW*11 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd12) ? w[MEMW*12 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd13) ? w[MEMW*13 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd14) ? w[MEMW*14 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd15) ? w[MEMW*15 +: MEMW] : '0);
  end
  for (genvar j = 0; j < E; j++) begin : g_col
    logic [18*2-1:0] tv;
    for (genvar t = 0; t < 2; t++) begin : g_t
      logic [18-1:0] ex;
      assign ex = {2'd0, xt[MEMW*t + 16*j +: 16]};
      assign tv[18*t +: 18] = quse[t] ? (qneg[t] ? (18'd0 - ex) : ex) : 18'd0;
    end
    logic [18-1:0] sum;
    assign sum = tv[18*0 +: 18] + tv[18*1 +: 18];
    logic [19*(j+1)-1:0] d;
    if (j == 0) begin : g_first
      always_ff @(posedge clk) d <= {swap, sum};
    end else begin : g_rest
      always_ff @(posedge clk) d <= {d[19*j-1:0], swap, sum};
    end
    assign swap_o[j]       = d[19*j + 18];
    assign x_o[18*j +: 18] = d[19*j +: 18];
  end
endmodule

// Array a: E rows; activations, the swap tag and the accumulate control travel down the rows.
module gemm_array_a #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic [(1<<LGE)-1:0] ld,
  input  logic [(1<<((LGE>3)?LGE-3:1))-1:0] ld_hi,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [(1<<LGE)-1:0] swap,
  input  logic [18*(1<<LGE)-1:0] x,
  input  logic [LGE+2+45-1:0] acw,
  input  logic                r_rd,
  input  logic [4-1:0]     r_g,
  input  logic [2-1:0]     r_sub,
  input  logic [LGE+2-1:0] r_v,
  output logic [48*(1<<LGE)-1:0] d
);
  localparam int E = 1 << LGE;
  localparam int XB = 18 * E;
  localparam int ACW = LGE + 2 + 45;
  localparam int LGR = (LGE < 3) ? LGE : 3;          // log2 of the tile rows in one beat of upper bits
  logic [E*(E+1)-1:0]    sw;
  logic [XB*(E+1)-1:0]   xx;
  logic [ACW*(E+1)-1:0]  ac;
  assign sw[E-1:0]   = swap;
  assign xx[XB-1:0]  = x;
  assign ac[ACW-1:0] = acw;
  for (genvar i = 0; i < E; i++) begin : g_row
    gemm_row_a #(.LGE(LGE)) u (
      .clk(clk), .ld(ld[i]), .ld_hi(ld_hi[i >> LGR]), .w_d(w_d),
      .w_h(w_d[2*E*(i & ((1 << LGR) - 1)) +: 2*E]),
      .swap_in(sw[E*i +: E]), .x_in(xx[XB*i +: XB]), .acw(ac[ACW*i +: ACW]),
      .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v),
      .swap_out(sw[E*(i+1) +: E]), .x_out(xx[XB*(i+1) +: XB]), .acw_o(ac[ACW*(i+1) +: ACW]),
      .dout(d[48*i +: 48]));
  end
endmodule

// One row of array a: E cells and the row's accumulators (the groups this array's products update), as in the
// shared-array designs; the read-out selects one word into the register `dout` (the output stage is outside:
// it adds the three arrays' partial sums).
module gemm_row_a #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic                ld, ld_hi,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [2*(1<<LGE)-1:0] w_h,
  input  logic [(1<<LGE)-1:0] swap_in,
  input  logic [18*(1<<LGE)-1:0] x_in,
  input  logic [LGE+2+45-1:0] acw,
  input  logic                r_rd,
  input  logic [4-1:0]     r_g,
  input  logic [2-1:0]     r_sub,
  input  logic [LGE+2-1:0] r_v,
  output logic [(1<<LGE)-1:0] swap_out,
  output logic [18*(1<<LGE)-1:0] x_out,
  output logic [LGE+2+45-1:0] acw_o,
  output logic [47:0]         dout
);
  localparam int E = 1 << LGE;
  localparam int KW = LGE + 2;
  logic [48*(E+1)-1:0] s;
  assign s[47:0] = 48'd0;
  for (genvar j = 0; j < E; j++) begin : g_cell
    gemm_cell_a u (.clk(clk), .ld(ld), .ld_hi(ld_hi), .w_d(w_d[16*j +: 16]), .w_h(w_h[2*j +: 2]),
                   .swap_in(swap_in[j]), .x_in(x_in[18*j +: 18]),
                   .s_in(s[48*j +: 48]), .swap_out(swap_out[j]), .x_out(x_out[18*j +: 18]),
                   .s_out(s[48*(j+1) +: 48]));
  end

  logic [47:0] sp, sn;
  logic [48*9-1:0] pk;
  logic        r_par;
  assign sp = s[48*E +: 48];
  assign sn = 48'd0 - sp;
  begin : g_acc0                                    // group 0: 1 result block(s)
    localparam int AG = LGE + 2 - 1 + 0;    // address bits: slot, vector / 2
    logic        en, en_o, ng_o, fi_o, rdr;
    logic [2-1:0] sub, sub_o;
    logic [47:0] d0, d1, wd;
    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*0];
    assign sub   = acw[KW + 5*0 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*0];
    assign ng_o  = acw_o[KW + 5*0 + 1];
    assign fi_o  = acw_o[KW + 5*0 + 2];
    assign sub_o = acw_o[KW + 5*0 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd0);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
    if (AG <= 8) begin : g_256
      srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[7:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                 .write(wr0), .dataout(d0));
      srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[7:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                 .write(wr1), .dataout(d1));
    end else if (AG == 9) begin : g_512
