    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*6];
    assign sub   = acw[KW + 5*6 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*6];
    assign ng_o  = acw_o[KW + 5*6 + 1];
    assign fi_o  = acw_o[KW + 5*6 + 2];
    assign sub_o = acw_o[KW + 5*6 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd6);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
    if (AG <= 8) begin : g_256
      srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[7:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                 .write(wr0), .dataout(d0));
      srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[7:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                 .write(wr1), .dataout(d1));
    end else if (AG == 9) begin : g_512
      srambank_128x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[8:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_128x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[8:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end else begin : g_1024
      srambank_256x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_256x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end
    logic        selg;
    always_ff @(posedge clk)
      if (r_rd) selg <= (r_g == 4'd6);
    assign pk[48*6 +: 48] = selg ? (r_par ? d1 : d0) : 48'd0;
  end

  begin : g_acc7                                    // group 7: 2 result block(s)
    localparam int AG = LGE + 2 - 1 + 1;    // address bits: slot, vector / 2
    logic        en, en_o, ng_o, fi_o, rdr;
    logic [2-1:0] sub, sub_o;
    logic [47:0] d0, d1, wd;
    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*7];
    assign sub   = acw[KW + 5*7 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*7];
    assign ng_o  = acw_o[KW + 5*7 + 1];
    assign fi_o  = acw_o[KW + 5*7 + 2];
    assign sub_o = acw_o[KW + 5*7 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd7);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
    if (AG <= 8) begin : g_256
      srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[7:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                 .write(wr0), .dataout(d0));
      srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[7:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                 .write(wr1), .dataout(d1));
    end else if (AG == 9) begin : g_512
      srambank_128x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[8:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_128x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[8:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end else begin : g_1024
      srambank_256x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_256x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end
    logic        selg;
    always_ff @(posedge clk)
      if (r_rd) selg <= (r_g == 4'd7);
    assign pk[48*7 +: 48] = selg ? (r_par ? d1 : d0) : 48'd0;
  end

  begin : g_acc8                                    // group 8: 4 result block(s)
    localparam int AG = LGE + 2 - 1 + 2;    // address bits: slot, vector / 2
    logic        en, en_o, ng_o, fi_o, rdr;
    logic [2-1:0] sub, sub_o;
    logic [47:0] d0, d1, wd;
    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*8];
    assign sub   = acw[KW + 5*8 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*8];
    assign ng_o  = acw_o[KW + 5*8 + 1];
    assign fi_o  = acw_o[KW + 5*8 + 2];
    assign sub_o = acw_o[KW + 5*8 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd8);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
    if (AG <= 8) begin : g_256
      srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[7:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                 .write(wr0), .dataout(d0));
      srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[7:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                 .write(wr1), .dataout(d1));
    end else if (AG == 9) begin : g_512
      srambank_128x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[8:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_128x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[8:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end else begin : g_1024
      srambank_256x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                  .write(wr0), .dataout(d0));
      srambank_256x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                  .write(wr1), .dataout(d1));
    end
    logic        selg;
    always_ff @(posedge clk)
      if (r_rd) selg <= (r_g == 4'd8);
    assign pk[48*8 +: 48] = selg ? (r_par ? d1 : d0) : 48'd0;
  end
  always_ff @(posedge clk) begin
    acw_o <= acw;
    if (r_rd) r_par <= r_v[0];
    dout  <= pk[48*0 +: 48] | pk[48*1 +: 48] | pk[48*2 +: 48] | pk[48*3 +: 48] | pk[48*4 +: 48] | pk[48*5 +: 48] | pk[48*6 +: 48] | pk[48*7 +: 48] | pk[48*8 +: 48];
  end
endmodule

// One multiply-accumulate cell of array a: signed 18-bit weight times signed 18-bit activation operand, exact,
// accumulated modulo 2^48; the weight double-buffered as in every design of this file.
module gemm_cell_a (
  input  logic        clk,
  input  logic        ld, ld_hi,
  input  logic [15:0] w_d,
  input  logic [1:0]  w_h,
  input  logic        swap_in,
  input  logic [17:0] x_in,
  input  logic [47:0] s_in,
  output logic        swap_out,
  output logic [17:0] x_out,
  output logic [47:0] s_out
);
  logic [18-1:0]        w_sh, w_act;
  logic signed [36-1:0] p;
  assign p = $signed(w_act) * $signed(x_in);
  always_ff @(posedge clk) begin
    if (ld)    w_sh[15:0] <= w_d;
    if (ld_hi) w_sh[18-1:16] <= w_h[18-17:0];
    if (swap_in) w_act <= w_sh;
    swap_out <= swap_in;
    x_out    <= x_in;
    s_out    <= s_in + {{12{p[36-1]}}, p};
  end
endmodule

// The operand and the input skew: the up to 4 blocks read from the buffer are added with their signs, entry by
// entry (a signed 18-bit operand), and column j of the result (and the swap tag) is delayed j + 1 cycles, so
// that every cell of a row sees its activation one cycle after its left neighbour's sum.
module gemm_skew_b #(parameter int LGE = 2) (
  input  logic                   clk,
  input  logic                   swap,
  input  logic [(16<<LGE)*(16<<((LGE+5>10)?LGE+5-10:0))-1:0] q,
  input  logic [1:0]             mode,
  input  logic [5-1:0]      qpid,
  input  logic [((LGE+5>10)?LGE+5-10:0):0] qsb,
  output logic [(1<<LGE)-1:0]    swap_o,
  output logic [18*(1<<LGE)-1:0] x_o
);
  localparam int E = 1 << LGE;
  localparam int MEMW = 16 * E;
  localparam int AW = LGE + 5;
  localparam int LGS = (AW > 10) ? AW - 10 : 0;
  logic [4*(2+4)-1:0] ptx;                    // the operand of product qpid: per term {use, negate, block}
  logic [4*4-1:0] qblk;
  logic [4-1:0] quse, qneg;
  always_comb begin
    case ({mode, qpid})
      7'd64: ptx = 24'hfebd61;
      7'd65: ptx = 24'heaec24;
      7'd66: ptx = 24'hffa9e2;
      7'd67: ptx = 24'hbfbde3;
      7'd68: ptx = 24'habeca6;
      7'd69: ptx = 24'hefa8e2;
      7'd70: ptx = 24'hffe9e6;
      7'd71: ptx = 24'hd70b68;
      7'd72: ptx = 24'h971f69;
      7'd73: ptx = 24'h834e2c;
      7'd74: ptx = 24'hc70a68;
      7'd75: ptx = 24'hd74b6c;
      7'd76: ptx = 24'hde3d61;
      7'd77: ptx = 24'hca6c24;
      7'd78: ptx = 24'hfebf69;
      7'd79: ptx = 24'heaee2c;
      default: ptx = '0;
    endcase
  end
  for (genvar t = 0; t < 4; t++) begin : g_op
    assign qblk[4*t +: 4] = ptx[(2+4)*t +: 4];
    assign qneg[t] = ptx[(2+4)*t + 4];
    assign quse[t] = ptx[(2+4)*t + 4 + 1];
  end
  logic [MEMW*16-1:0] w;                          // per bank: the word of the sub-bank that was read
  for (genvar b = 0; b < 16; b++) begin : g_b
    if (LGS == 0) begin : g_1
      assign w[MEMW*b +: MEMW] = q[MEMW*b +: MEMW];
    end else if (LGS == 1) begin : g_2
      assign w[MEMW*b +: MEMW] = qsb[0] ? q[MEMW*(2*b+1) +: MEMW] : q[MEMW*(2*b) +: MEMW];
    end else begin : g_4                             // LGE <= 7: at most four sub-banks
      assign w[MEMW*b +: MEMW] = qsb[1] ? (qsb[0] ? q[MEMW*(4*b+3) +: MEMW] : q[MEMW*(4*b+2) +: MEMW])
                                        : (qsb[0] ? q[MEMW*(4*b+1) +: MEMW] : q[MEMW*(4*b) +: MEMW]);
    end
  end
  logic [MEMW*4-1:0] xt;                         // per term: the selected bank's beat, an OR over the banks
  for (genvar t = 0; t < 4; t++) begin : g_term
    assign xt[MEMW*t +: MEMW] = ((qblk[4*t +: 4] == 4'd0) ? w[MEMW*0 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd1) ? w[MEMW*1 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd2) ? w[MEMW*2 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd3) ? w[MEMW*3 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd4) ? w[MEMW*4 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd5) ? w[MEMW*5 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd6) ? w[MEMW*6 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd7) ? w[MEMW*7 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd8) ? w[MEMW*8 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd9) ? w[MEMW*9 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd10) ? w[MEMW*10 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd11) ? w[MEMW*11 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd12) ? w[MEMW*12 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd13) ? w[MEMW*13 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd14) ? w[MEMW*14 +: MEMW] : '0)
        | ((qblk[4*t +: 4] == 4'd15) ? w[MEMW*15 +: MEMW] : '0);
  end
  for (genvar j = 0; j < E; j++) begin : g_col
    logic [18*4-1:0] tv;
    for (genvar t = 0; t < 4; t++) begin : g_t
      logic [18-1:0] ex;
      assign ex = {2'd0, xt[MEMW*t + 16*j +: 16]};
      assign tv[18*t +: 18] = quse[t] ? (qneg[t] ? (18'd0 - ex) : ex) : 18'd0;
    end
    logic [18-1:0] sum;
    assign sum = tv[18*0 +: 18] + tv[18*1 +: 18] + tv[18*2 +: 18] + tv[18*3 +: 18];
    logic [19*(j+1)-1:0] d;
    if (j == 0) begin : g_first
      always_ff @(posedge clk) d <= {swap, sum};
    end else begin : g_rest
      always_ff @(posedge clk) d <= {d[19*j-1:0], swap, sum};
    end
    assign swap_o[j]       = d[19*j + 18];
    assign x_o[18*j +: 18] = d[19*j +: 18];
  end
endmodule

// Array b: E rows; activations, the swap tag and the accumulate control travel down the rows.
module gemm_array_b #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic [(1<<LGE)-1:0] ld,
  input  logic [(1<<((LGE>3)?LGE-3:1))-1:0] ld_hi,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [(1<<LGE)-1:0] swap,
  input  logic [18*(1<<LGE)-1:0] x,
  input  logic [LGE+2+45-1:0] acw,
  input  logic                r_rd,
  input  logic [4-1:0]     r_g,
  input  logic [2-1:0]     r_sub,
  input  logic [LGE+2-1:0] r_v,
  output logic [48*(1<<LGE)-1:0] d
);
  localparam int E = 1 << LGE;
  localparam int XB = 18 * E;
  localparam int ACW = LGE + 2 + 45;
  localparam int LGR = (LGE < 3) ? LGE : 3;          // log2 of the tile rows in one beat of upper bits
  logic [E*(E+1)-1:0]    sw;
  logic [XB*(E+1)-1:0]   xx;
  logic [ACW*(E+1)-1:0]  ac;
  assign sw[E-1:0]   = swap;
  assign xx[XB-1:0]  = x;
  assign ac[ACW-1:0] = acw;
  for (genvar i = 0; i < E; i++) begin : g_row
    gemm_row_b #(.LGE(LGE)) u (
      .clk(clk), .ld(ld[i]), .ld_hi(ld_hi[i >> LGR]), .w_d(w_d),
      .w_h(w_d[2*E*(i & ((1 << LGR) - 1)) +: 2*E]),
      .swap_in(sw[E*i +: E]), .x_in(xx[XB*i +: XB]), .acw(ac[ACW*i +: ACW]),
      .r_rd(r_rd), .r_g(r_g), .r_sub(r_sub), .r_v(r_v),
      .swap_out(sw[E*(i+1) +: E]), .x_out(xx[XB*(i+1) +: XB]), .acw_o(ac[ACW*(i+1) +: ACW]),
      .dout(d[48*i +: 48]));
  end
endmodule

// One row of array b: E cells and the row's accumulators (the groups this array's products update), as in the
// shared-array designs; the read-out selects one word into the register `dout` (the output stage is outside:
// it adds the three arrays' partial sums).
module gemm_row_b #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic                ld, ld_hi,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [2*(1<<LGE)-1:0] w_h,
  input  logic [(1<<LGE)-1:0] swap_in,
  input  logic [18*(1<<LGE)-1:0] x_in,
  input  logic [LGE+2+45-1:0] acw,
  input  logic                r_rd,
  input  logic [4-1:0]     r_g,
  input  logic [2-1:0]     r_sub,
  input  logic [LGE+2-1:0] r_v,
  output logic [(1<<LGE)-1:0] swap_out,
  output logic [18*(1<<LGE)-1:0] x_out,
  output logic [LGE+2+45-1:0] acw_o,
  output logic [47:0]         dout
);
  localparam int E = 1 << LGE;
  localparam int KW = LGE + 2;
  logic [48*(E+1)-1:0] s;
  assign s[47:0] = 48'd0;
  for (genvar j = 0; j < E; j++) begin : g_cell
    gemm_cell_b u (.clk(clk), .ld(ld), .ld_hi(ld_hi), .w_d(w_d[16*j +: 16]), .w_h(w_h[2*j +: 2]),
                   .swap_in(swap_in[j]), .x_in(x_in[18*j +: 18]),
                   .s_in(s[48*j +: 48]), .swap_out(swap_out[j]), .x_out(x_out[18*j +: 18]),
                   .s_out(s[48*(j+1) +: 48]));
  end

  logic [47:0] sp, sn;
  logic [48*9-1:0] pk;
  logic        r_par;
  assign sp = s[48*E +: 48];
  assign sn = 48'd0 - sp;
  begin : g_acc0                                    // group 0: 1 result block(s)
    localparam int AG = LGE + 2 - 1 + 0;    // address bits: slot, vector / 2
    logic        en, en_o, ng_o, fi_o, rdr;
    logic [2-1:0] sub, sub_o;
    logic [47:0] d0, d1, wd;
    logic        rd0, rd1, wr0, wr1;
    logic [9:0]  a_w, a_a, a_r, ad0, ad1;
    assign en    = acw[KW + 5*0];
    assign sub   = acw[KW + 5*0 + 3 +: 2];
    assign en_o  = acw_o[KW + 5*0];
    assign ng_o  = acw_o[KW + 5*0 + 1];
    assign fi_o  = acw_o[KW + 5*0 + 2];
    assign sub_o = acw_o[KW + 5*0 + 3 +: 2];
    assign rdr   = r_rd & (r_g == 4'd0);
    assign a_w   = 10'({sub_o, acw_o[KW-1:0]} >> 1);
    assign a_a   = 10'({sub, acw[KW-1:0]} >> 1);
    assign a_r   = 10'({r_sub, r_v} >> 1);
    assign wr0   = en_o & ~acw_o[0];
    assign wr1   = en_o &  acw_o[0];
    assign rd0   = (en & ~acw[0]) | (rdr & ~r_v[0]);
    assign rd1   = (en &  acw[0]) | (rdr &  r_v[0]);
    assign ad0   = wr0 ? a_w : en ? a_a : a_r;
    assign ad1   = wr1 ? a_w : en ? a_a : a_r;
    assign wd    = (fi_o ? 48'd0 : (acw_o[0] ? d1 : d0)) + (ng_o ? sn : sp);
    if (AG <= 8) begin : g_256
      srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0[7:0]), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                                 .write(wr0), .dataout(d0));
      srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1[7:0]), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                                 .write(wr1), .dataout(d1));
    end else if (AG == 9) begin : g_512
